    /// Sign up with OAuth provider
    ///
    /// Initiate OAuth signup flow with the specified provider. Redirects to the provider's authorization page.
    /// Use this endpoint to explicitly register a new account. When \`AUTH\_DISABLE\_AUTO\_SIGNUP\` is enabled, this is the only way to register through this method.
    /// If the user already exists at callback time, they are redirected with \`error=user\-already\-exists\`.
    ///
    /// Builds the URL for GET /signup/provider/{provider} without following the redirect.
    pub fn sign_up_provider_url(
        &self,
        provider: &str,
        params: Option<&SignUpProviderParams>,
    ) -> Result<String, Error> {
        let mut url = http::append_path(self.base_url.as_str(), &["signup", "provider", provider])?
            .to_string();
        if let Some(p) = params {
            let q = p.to_query();
            if !q.is_empty() {
                let qs = q
                    .iter()
                    .map(|(k, v)| format!("{}={}", urlencode(k), urlencode(v)))
                    .collect::<Vec<_>>()
                    .join("&");
                url.push('?');
                url.push_str(&qs);
            }
        }
        Ok(url)
    }

    /// Builds the refresh-token request shared by the public API and session runtime.
    pub(crate) fn refresh_token_request(
        &self,
        body: &RefreshTokenRequest,
    ) -> Result<http::RequestBuilder, Error> {
        let url = http::append_path(self.base_url.as_str(), &["token"])?;
        Ok(self.http.request(reqwest::Method::POST, url).json(body))
    }

    /// Refresh access token
